    // ── 0. A type parameter in scope shadows any declaration of the same name ──
    if args.is_empty() && state.has_type_param(name) {
        return PropType::Named { name: name.clone(), args: Vec::new() };
    }

    // ── 1. React builtin check ────────────────────────────────────────────────
