        }
        "Required" if !args.is_empty() => {
            Some(CollectedTypeAlias::Required { base: args[0].clone(), file_path: file_path.to_owned() })
        }
        // `PropsWithChildren<P>` is `P & { children?: ReactNode }`, and with no argument (`P = unknown`) only the
